var zod = require('zod');
require('pino');
var units = require('@ethersproject/units');

// ----------------------------------------------------------------------------
// IRIS API base URLs
// ----------------------------------------------------------------------------
/** Production IRIS API host (mainnet chains). */ const IRIS_API_BASE_URL = 'https://iris-api.circle.com';
/** Sandbox IRIS API host (testnet chains). */ const IRIS_API_SANDBOX_BASE_URL = 'https://iris-api-sandbox.circle.com';
// ----------------------------------------------------------------------------
// IRIS API path templates
// ----------------------------------------------------------------------------
//
// Paths are relative to the IRIS base URL (sandbox for testnet, prod for
// mainnet — resolved at call time by the provider). Templated segments use
// `{name}` placeholders; the fetchers substitute the concrete values.
/** `GET` — returns all CCTPx tokens listed in the IRIS registry. */ const CCTPX_TOKENS_PATH = '/v2/cctpx/tokens';
/**
 * `POST` — returns a server-signed fee quote for a CCTPx transfer of the
 * given `tokenId` between the named source and destination domains.
 */ const CCTPX_FEE_QUOTE_PATH = '/v2/quote/cctpx/{tokenId}/{sourceDomain}/{destinationDomain}';
/**
 * `GET` — returns the remaining fast-burn allowance for the given
 * `tokenIds` (a comma-separated query param of bytes32 token ids). Backs
 * the orchestrator's FAST→SLOW degrade (the `isFastBurnAvailable` context
 * hook): a FAST transfer over the remaining allowance is not rejected
 * on-chain, it settles at finality anyway with the `PRE_FINALITY` premium
 * already paid — so the bridge probes this endpoint before signing and
 * re-prices at SLOW (emitting a fast-burn-unavailable signal) rather than
 * charging for a speed it will not get. See `fetchCCTPXAllowances`.
 */ const CCTPX_ALLOWANCES_PATH = '/v2/cctpx/allowances';
/**
 * `GET` — returns the attestation envelope and forward state for a
 * source-chain CCTPx message. Reused unchanged from the CCTP v2 polling
 * path.
 */ const CCTPX_MESSAGES_PATH = '/v2/messages/{sourceDomain}';
/**
 * `POST` — requests a fresh attestation for a stuck CCTPx message by its
 * `nonce` when the original could not be delivered. Fire-and-forget: IRIS
 * acknowledges with an opaque body and re-signs on a periodic cron.
 */ const CCTPX_REATTEST_PATH = '/v2/reattest/{nonce}';
// ----------------------------------------------------------------------------
// On-chain protocol constants
// ----------------------------------------------------------------------------
/**
 * Bound on an on-chain confirmation wait, in milliseconds.
 *
 * Applied to every `waitForTransaction` the bridge makes, on both the
 * sequential and the batched path, so the two behave the same way.
 *
 * Without it the wait is only as bounded as the adapter makes it, and that
 * differs per adapter: the `/next` viem adapter surfaces viem's own 180s
 * receipt timeout, while ethers installs no reject timer at all unless one is
 * supplied — so on ethers a transaction that never mines would park the bridge
 * call forever. `retryAsync` cannot rescue that: it retries a *rejected*
 * promise, and a wait that never settles produces no rejection to retry.
 *
 * 180s matches viem's own default rather than inventing a stricter number, so
 * bounding the wait does not start failing transactions that viem would still
 * be waiting on. It is also passed as `retryAsync`'s `deadlineMs`, so a retry
 * loop stops starting new attempts once it elapses rather than granting each
 * attempt its own full window. It is not a ceiling on the call: a deadline
 * blocks the *next* attempt, it does not truncate one already running, and a
 * batched bundle runs one loop per call. Budget for roughly twice this per
 * loop, times the number of calls in the bundle.
 *
 * A source transaction needs one confirmation, so the value is a function of
 * source-chain block time, not of the transfer's finality threshold — `FAST`
 * speeds up destination delivery, not source inclusion.
 *
 * A timed-out wait records an error step that keeps the transaction hash, so
 * the transfer stays resumable rather than lost.
 */ const ONCHAIN_CONFIRM_TIMEOUT_MS = 180_000;
/**
 * `minFinalityThreshold` values accepted by `crossChainTransfer`.
 *
 * - `FAST` = 1000 — pre-finality delivery, requires a `PRE_FINALITY`
 *   fee item in the signed quote and consumes fast-burn allowance.
 * - `SLOW` = 2000 — full finality, lower fee, always available.
 */ const MIN_FINALITY_THRESHOLD = {
    FAST: 1000,
    SLOW: 2000
};
