const CIRBTC_MAINNET_TOKEN_ID = '0x3d26699fb5d40190fc3fa0dcbc1cd24e558355043c1997572ff9fd6efbb3fdca';
const WETH_TESTNET_TOKEN_ID = '0xaa3cf4df2d82ec4b91da19afe54d414f637d068fe9cd52ba5e0e7e0d94f9eac8';
const WETH_MAINNET_TOKEN_ID = '0x5c2cf12eccf48ab63313169ce192dc00af7c37a58bbc546ba4becf54df4962ea';
