                endpoint: path,
                unreachableMessage: 'CCTPx fee quote unreachable',
                httpErrorMessage: (status)=>`CCTPx fee quote request failed with status ${status}`,
                invalidPayloadMessage: 'CCTPx fee quote response invalid',
                schemaLabel: 'CCTPx fee quote response',
                includeErrorBody: true,
                includeHttpRawError: true
