        signedQuote: quote.signedQuote,
        issuedAt: quote.issuedAt,
        expiryMode: quote.expiry.mode,
        feeToken: quote.feeToken,
        nonce: quote.nonce,
        feeTotalAmount: quote.feeTotalAmount,
        items: quote.items
