    // statuses — 404, 429, and any 5xx (`>= 500` covers the whole server-error
    // range; HTTP has no 6xx) — and treat every other 4xx as terminal. A
    // non-numeric `http_unknown` parses to NaN and falls through to terminal.
    const status = Number(failure.slice('http_'.length));
