/** USDC is 6-decimal on every supported chain. */ const USDC_DECIMALS = 6;
/**
 * Resolve the display symbol and decimal precision of a quote's fee token.
 *
 * The IRIS fee quote denominates fees in `feeToken` — either the native
 * currency (the zero address) or an ERC-20 address — and reports the total as
 * a raw integer. Formatting the `EstimateResult.fees[]` summary needs both a
 * human-friendly symbol and the scale to divide by, and the two must describe
 * the *same* token or the summary lies. Resolving them together in one pass is
 * what guarantees that; they were previously two functions whose agreement
 * rested on their bodies happening to match.
 *
 * The resolution order is:
 *
 * 1. The zero address (native fee token) → the source chain's
 *    `nativeCurrency` symbol and decimals (e.g. `'ETH'` / 18). Critically,
 *    this holds even when the native symbol happens to be `'USDC'` (Arc),
 *    where the native decimals are 18, not 6 — so the fee is never
 *    mis-scaled by resolving through a USDC token entry.
 * 2. The source chain's USDC address (case-insensitive) → `'USDC'` / 6.
 * 3. A CCTPx registry deployment matching `(sourceDomain, feeToken)` → that
 *    token's registry `symbol` and `decimals`. The symbol passes through
 *    exactly as the registry serves it, which is not always the casing the
 *    rest of the SDK uses: the registry lists wETH as `'WETH'`, so that is
 *    what `EstimateResult.fees[].token` carries, while the known-symbol list
 *    spells the same token `'wETH'`. Compare fee symbols case-insensitively.
 * 4. Unknown ERC-20 → the lowercased raw address, and `undefined` decimals.
 *    The symbol field is always populated; the decimals field deliberately
 *    is not, so the caller leaves the amount raw rather than mis-scale it.
 *
 * Do NOT use the provider's `getTokenDecimals` hook for step 3: that resolves
 * the TRANSFER token, and for a native fee labeled `'USDC'` it would return 6
 * and mis-scale the fee by 10^12. The fee-token lookup is a separate one.
 *
 * The registry is already cached on the provider instance when this runs, so
 * the lookup is synchronous and in-memory.
 *
 * @param feeToken - The fee token address from the signed quote.
 * @param srcChain - The source chain definition (native currency, USDC
 *   address, and the CCTP domain for the registry lookup).
 * @param registry - The cached CCTPx token registry to resolve against.
 * @returns The fee token's {@link FeeTokenDisplay} symbol and decimals.
 *
 * @example
 * ```typescript
 * import { Ethereum } from '@core/chains'
 *
 * const { symbol, decimals } = feeTokenDisplay(
 *   '0x0000000000000000000000000000000000000000',
 *   Ethereum,
 *   registry,
 * )
 * console.log(symbol, decimals) // 'ETH' 18
 * ```
 */ function feeTokenDisplay(feeToken, srcChain, registry) {
    const normalizedFeeToken = feeToken.toLowerCase();
    // 1. Native currency (zero address) → chain's native symbol and decimals.
    if (normalizedFeeToken === NATIVE_FEE_TOKEN.toLowerCase()) {
        return {
            symbol: srcChain.nativeCurrency.symbol,
            decimals: srcChain.nativeCurrency.decimals
        };
    }
    // 2. Chain's USDC address (case-insensitive) → 'USDC' / 6.
    if (srcChain.usdcAddress !== null && srcChain.usdcAddress.toLowerCase() === normalizedFeeToken) {
        return {
            symbol: 'USDC',
            decimals: USDC_DECIMALS
        };
    }
    // 3. A CCTPx registry deployment on the source domain whose token address
    //    matches the fee token → that token's registry symbol and decimals.
    //    Matching on BOTH `domainId` and `tokenAddress` is load-bearing:
    //    `findCCTPXDeployment` from lookup.ts matches the domain only, so it
    //    would resolve an unrelated token deployed on the same domain.
    const sourceDomain = srcChain.cctp?.domain;
    if (sourceDomain !== undefined) {
        for (const token of registry.tokens){
            const matches = token.deployments.some((deployment)=>deployment.domainId === sourceDomain && deployment.tokenAddress.toLowerCase() === normalizedFeeToken);
            if (matches) {
                return {
                    symbol: token.symbol,
                    decimals: token.decimals
                };
            }
        }
    }
    // 4. Unknown ERC-20 — the raw address keeps the symbol field populated,
    //    while undefined decimals tell the caller to leave the amount raw.
    return {
        symbol: normalizedFeeToken,
        decimals: undefined
    };
}

/** Default cache TTL: 5 minutes. */ const DEFAULT_TOKEN_REGISTRY_TTL_MS = 5 * 60 * 1000;
